import * as THREE from 'three';
import type { WorldCollider, WorldParts } from './world';
import { terrainHeight } from './world';

export class PlayerMotor {
  readonly velocity = new THREE.Vector3();
  grounded = false;
  private dodgeVelocity = new THREE.Vector3();
  private verticalVelocity = 0;
  constructor(private root: THREE.Group, private colliders: WorldCollider[]) {}
  get verticalSpeed() { return this.verticalVelocity; }

  reset() {
    this.velocity.set(0, 0, 0);
    this.dodgeVelocity.set(0, 0, 0);
    this.verticalVelocity = 0;
    this.grounded = true;
  }

  dodge(facingYaw: number, side = 0) {
    const forward = new THREE.Vector3(-Math.sin(facingYaw), 0, -Math.cos(facingYaw));
    const right = new THREE.Vector3(Math.cos(facingYaw), 0, -Math.sin(facingYaw));
    this.dodgeVelocity.copy(forward).multiplyScalar(side < 0 ? -1 : 1);
    if (Math.abs(side) > .35) this.dodgeVelocity.copy(right).multiplyScalar(Math.sign(side));
    this.dodgeVelocity.multiplyScalar(8.5);
  }

  update(delta: number, moveForward: number, moveSide: number, sprint: boolean, jump: boolean, facingYaw: number, flight = false, verticalInput = 0, cameraPitch = 0) {
    const inputLength = Math.hypot(moveForward, moveSide);
    let desiredX = 0, desiredZ = 0;
    if (inputLength > 0) {
      const fX = -Math.sin(facingYaw), fZ = -Math.cos(facingYaw);
      const rX = Math.cos(facingYaw), rZ = -Math.sin(facingYaw);
      desiredX = (fX * moveForward + rX * moveSide) / inputLength;
      desiredZ = (fZ * moveForward + rZ * moveSide) / inputLength;
      const speed = flight ? (sprint ? 7.6 : 5.2) : (sprint ? 7.4 : 4.35);
      desiredX *= speed; desiredZ *= speed;
    }
    const response = inputLength > 0 ? 16 : 20;
    this.velocity.x = THREE.MathUtils.damp(this.velocity.x, desiredX, response, delta);
    this.velocity.z = THREE.MathUtils.damp(this.velocity.z, desiredZ, response, delta);

    this.dodgeVelocity.multiplyScalar(Math.exp(-delta * 8));
    const movementX = this.velocity.x + this.dodgeVelocity.x, movementZ = this.velocity.z + this.dodgeVelocity.z;
    const steps = Math.max(1, Math.ceil(Math.hypot(movementX, movementZ) * delta / .22));
    const stepDelta = delta / steps;
    for (let step = 0; step < steps; step++) {
      let x = this.root.position.x + movementX * stepDelta;
      let z = this.root.position.z + movementZ * stepDelta;
      x = THREE.MathUtils.clamp(x, -105, 105); z = THREE.MathUtils.clamp(z, -105, 105);
      for (const collider of this.colliders) {
        let dx = x - collider.x, dz = z - collider.z;
        const minimum = collider.radius + .31;
        const distance = Math.hypot(dx, dz);
        if (distance < minimum) {
          if (distance < .0001) { dx = .001; dz = 0; }
          const length = Math.hypot(dx, dz);
          x = collider.x + (dx / length) * minimum;
          z = collider.z + (dz / length) * minimum;
          const normalVelocity = this.velocity.x * (dx / length) + this.velocity.z * (dz / length);
          if (normalVelocity < 0) {
            this.velocity.x -= normalVelocity * (dx / length);
            this.velocity.z -= normalVelocity * (dz / length);
          }
        }
      }
      this.root.position.x = x; this.root.position.z = z;
    }

    const surfaceY = terrainHeight(this.root.position.x, this.root.position.z);
    if (flight) {
      const forwardLift = -moveForward * Math.sin(cameraPitch) * (sprint ? 7.6 : 5.2);
      this.verticalVelocity = THREE.MathUtils.damp(this.verticalVelocity, verticalInput * 4.4 + forwardLift, 8, delta);
      this.root.position.y = Math.max(surfaceY + .12, this.root.position.y + this.verticalVelocity * delta);
      this.grounded = false;
    } else if (this.root.position.y <= surfaceY + .06 && this.verticalVelocity <= 0) {
      this.root.position.y = surfaceY;
      this.verticalVelocity = 0;
      this.grounded = true;
    } else this.grounded = false;
    if (!flight && jump && this.grounded) {
      this.verticalVelocity = 9.4;
      this.grounded = false;
    }
    if (!flight) { this.verticalVelocity -= 26 * delta; this.root.position.y += this.verticalVelocity * delta; }
    if (!flight && this.root.position.y <= surfaceY) {
      this.root.position.y = surfaceY;
      this.verticalVelocity = 0;
      this.grounded = true;
    }

    if (inputLength > 0 && Math.hypot(this.velocity.x, this.velocity.z) > .2) {
      const facing = Math.atan2(this.velocity.x, this.velocity.z);
      this.root.userData.facing = facing;
    }
    return inputLength > 0 && Math.hypot(this.velocity.x, this.velocity.z) > .35 || this.dodgeVelocity.length() > .8;
  }
}

export class ThirdPersonCamera {
  yaw = 0;
  pitch = .19;
  distance = 9.2;
  aimRange = 40;
  sensitivity = .0032;
  targetHeight = 1.68;
  shoulderOffset = .9;
  shiftLockShoulderOffset = 1;
  minPitch = -.12;
  maxPitch = .72;
  followSharpness = 12;
  collisionReleaseSharpness = 7;
  collisionApproachSharpness = 18;
  minimumCollisionDistance = 3.8;
  collisionPadding = .36;
  minimumCameraHeight = .85;
  private currentDistance = 9.2;
  private readonly raycaster = new THREE.Raycaster();
  private readonly target = new THREE.Vector3();
  private readonly offset = new THREE.Vector3();
  private readonly desired = new THREE.Vector3();
  private readonly look = new THREE.Vector3();
  private readonly right = new THREE.Vector3();
  private readonly rayDirection = new THREE.Vector3();
  private readonly screenCenter = new THREE.Vector2(0, 0);
  private readonly collisionHits: THREE.Intersection[] = [];
  private readonly aimHits: THREE.Intersection[] = [];
  private shiftLocked = false;
  private collisionDistance = 9.2;
  private readonly collisionObjects: THREE.Object3D[];
  private readonly aimObjects: THREE.Object3D[];

  constructor(private camera: THREE.PerspectiveCamera, private parts: WorldParts) {
    // Forest meshes use a local camera fade; letting their instanced bounds
    // collapse the orbit distance causes the near-first-person camera snap.
    this.collisionObjects = parts.blockers.filter(object => object.name !== 'forest-trunks' && object.name !== 'field-stones');
    this.aimObjects = [...parts.blockers, parts.ground];
  }

  setShiftLock(enabled: boolean) { this.shiftLocked = enabled; }

  rotate(dx: number, dy: number) {
    this.yaw -= dx * this.sensitivity;
    this.yaw = THREE.MathUtils.euclideanModulo(this.yaw + Math.PI, Math.PI * 2) - Math.PI;
    this.pitch = THREE.MathUtils.clamp(this.pitch + dy * this.sensitivity, this.minPitch, this.maxPitch);
  }

  zoom(delta: number) {
    this.distance = THREE.MathUtils.clamp(this.distance + delta * .008, 5, 14);
  }

  update(root: THREE.Group, delta: number) {
    // Keep the screen-center aim slightly above the hero's torso so the full
    // character sits just below the reticle, as in an over-the-shoulder RPG.
    this.target.set(root.position.x, root.position.y + this.targetHeight, root.position.z);
    this.right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const horizontal = Math.cos(this.pitch) * this.distance;
    this.offset.set(Math.sin(this.yaw) * horizontal, Math.sin(this.pitch) * this.distance + .3, Math.cos(this.yaw) * horizontal);
    // The over-the-shoulder composition remains active so the center reticle
    // does not jump when Shift Lock is toggled; lock mode adds a small shoulder bias.
    this.offset.addScaledVector(this.right, this.shiftLocked ? this.shiftLockShoulderOffset : this.shoulderOffset);
    this.desired.copy(this.target).add(this.offset);
    this.raycaster.near = .1;
    this.raycaster.far = this.distance;
    this.rayDirection.copy(this.offset).normalize();
    this.raycaster.set(this.target, this.rayDirection);
    this.collisionHits.length = 0;
    const hit = this.raycaster.intersectObjects(this.collisionObjects, true, this.collisionHits).find(item => item.distance < this.distance - .2);
    // Keep the camera in a useful third-person view even when a nearby trunk
    // crosses the ray; canopies fade locally instead of forcing a first-person snap.
    const requestedDistance = hit ? Math.max(this.minimumCollisionDistance, hit.distance - this.collisionPadding) : this.distance;
    if (requestedDistance < this.collisionDistance) this.collisionDistance = requestedDistance;
    else this.collisionDistance = THREE.MathUtils.damp(this.collisionDistance, requestedDistance, this.collisionReleaseSharpness, delta);
    this.currentDistance = THREE.MathUtils.damp(this.currentDistance, this.collisionDistance, this.collisionApproachSharpness, delta);
    this.desired.copy(this.offset).setLength(this.currentDistance).add(this.target);
    this.desired.y = Math.max(this.desired.y, terrainHeight(this.desired.x, this.desired.z) + this.minimumCameraHeight);
    this.camera.position.lerp(this.desired, 1 - Math.exp(-delta * this.followSharpness));
    this.look.copy(this.target);
    this.look.addScaledVector(this.right, .12);
    this.camera.lookAt(this.look);
  }

  getAimPoint(out: THREE.Vector3, extraTargets: THREE.Object3D[] = []) {
    this.camera.updateMatrixWorld();
    extraTargets.forEach(target => target.updateWorldMatrix(true, false));
    this.raycaster.setFromCamera(this.screenCenter, this.camera);
    this.raycaster.near = .1;
    this.raycaster.far = this.aimRange;
    this.aimHits.length = 0;
    const visibleHit = this.raycaster.intersectObjects([...this.aimObjects, ...extraTargets], true, this.aimHits).find(hit => {
      const isLocallyFaded = hit.object.name === 'forest-trunks' || hit.object.name === 'field-stones';
      return !isLocallyFaded || hit.point.distanceTo(this.raycaster.ray.origin) >= 4.6;
    });
    if (visibleHit) out.copy(visibleHit.point);
    else this.raycaster.ray.at(this.aimRange, out);
    return out;
  }
}
