import * as THREE from 'three';
import { terrainHeight } from './world';
import type { LootItemId } from './progression';

export type MobKind = 'wolf' | 'bandit' | 'demon';
type Mob = {
  kind: MobKind;
  root: THREE.Group;
  target: THREE.Mesh;
  health: number;
  phase: number;
  attackTimer: number;
  respawnTimer: number;
  spawn: number;
  hitFlash: number;
  legs: THREE.Group[];
  arms: THREE.Group[];
  body: THREE.Group;
  head: THREE.Group;
  tail: THREE.Group | null;
  attackPhase: number;
  attackDuration: number;
  attackHit: boolean;
  gait: number;
  deathAge: number;
};
type Drop = { root: THREE.Group; kind: 'experience' | LootItemId; age: number; value: number; materials: THREE.Material[] };
type Spawn = { kind: MobKind; x: number; z: number };

const SPAWNS: Spawn[] = [
  { kind: 'wolf', x: -5.6, z: -23 }, { kind: 'wolf', x: 5.8, z: -29 }, { kind: 'wolf', x: 9, z: -39 },
  { kind: 'bandit', x: -9, z: -36 }, { kind: 'bandit', x: 7.5, z: -44 },
  { kind: 'demon', x: -2.5, z: -52 }, { kind: 'demon', x: 11, z: -60 },
];

const MOB_STATS: Record<MobKind, { hp: number; xp: number; speed: number; range: number; damage: number; cadence: number; radius: number }> = {
  wolf: { hp: 72, xp: 28, speed: 3.2, range: 1.35, damage: 5, cadence: 1.8, radius: .8 },
  bandit: { hp: 120, xp: 46, speed: 2.2, range: 2.1, damage: 9, cadence: 2.4, radius: .72 },
  demon: { hp: 190, xp: 82, speed: 1.8, range: 2.35, damage: 14, cadence: 2.7, radius: 1.05 },
};

const LOOT: Record<LootItemId, { color: string }> = {
  wolfPelt: { color: '#c3a77d' }, banditToken: { color: '#d0ad65' }, demonAsh: { color: '#a66a64' },
  moonFang: { color: '#b9d5ce' }, ancientSigil: { color: '#d6ba83' }, demonHeart: { color: '#ef6c63' },
};

function part(parent: THREE.Object3D, geometry: THREE.BufferGeometry, material: THREE.Material, position: [number, number, number], scale: [number, number, number] = [1, 1, 1], rotation: [number, number, number] = [0, 0, 0]) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...position); mesh.scale.set(...scale); mesh.rotation.set(...rotation);
  if (material instanceof THREE.MeshStandardMaterial) mesh.userData.baseEmissive = material.emissiveIntensity;
  mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh);
  return mesh;
}

/** Melee creature combat, low-poly mob silhouettes, respawning encounters, and physical XP/loot drops. */
export class CombatSystem {
  readonly targets: THREE.Object3D[] = [];
  readonly playerHealth = 100;
  health = 100;
  blocked = 0;
  private mobs: Mob[] = [];
  private drops: Drop[] = [];
  private root = new THREE.Group();
  private dropRoot = new THREE.Group();
  private geometries: THREE.BufferGeometry[] = [];
  private materials: THREE.Material[] = [];
  private sphere: THREE.SphereGeometry;
  private capsule: THREE.CapsuleGeometry;
  private cone: THREE.ConeGeometry;
  private cylinder: THREE.CylinderGeometry;
  private box: THREE.BoxGeometry;
  private itemMaterial = new THREE.MeshStandardMaterial({ color: '#e1d6a7', emissive: '#74633b', emissiveIntensity: .65, metalness: .18, roughness: .42 });
  private xpMaterial = new THREE.MeshStandardMaterial({ color: '#b9dcc2', emissive: '#74a886', emissiveIntensity: 1.15, roughness: .3, metalness: .12 });
  private targetMaterial = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
  private gemGeometry: THREE.OctahedronGeometry;
  private ringGeometry: THREE.TorusGeometry;

  constructor(private scene: THREE.Scene, private onExperience: (amount: number) => void = () => {}, private onItem: (item: LootItemId) => void = () => {}, private onPickup: (message: string) => void = () => {}) {
    this.root.name = 'hostile-mobs'; scene.add(this.root);
    this.dropRoot.name = 'mob-drops'; scene.add(this.dropRoot);
    this.sphere = this.geometry(new THREE.SphereGeometry(1, 18, 12));
    this.capsule = this.geometry(new THREE.CapsuleGeometry(.42, .72, 5, 10));
    this.cone = this.geometry(new THREE.ConeGeometry(.17, .48, 10));
    this.cylinder = this.geometry(new THREE.CylinderGeometry(.11, .14, .62, 10));
    this.box = this.geometry(new THREE.BoxGeometry(1, 1, 1));
    this.gemGeometry = this.geometry(new THREE.OctahedronGeometry(.2, 0));
    this.ringGeometry = this.geometry(new THREE.TorusGeometry(.3, .018, 6, 24));
    this.materials.push(this.itemMaterial, this.xpMaterial, this.targetMaterial);
    for (let index = 0; index < SPAWNS.length; index++) this.mobs.push(this.createMob(SPAWNS[index], index));
  }

  get alive() { return this.mobs.filter(mob => mob.health > 0).length; }

  respawnPlayer() { this.health = this.playerHealth; }

  damageAt(point: THREE.Vector3, radius: number, damage: number) {
    let count = 0;
    for (const mob of this.mobs) {
      if (mob.health <= 0) continue;
      const center = mob.root.position.clone().add(new THREE.Vector3(0, mob.kind === 'wolf' ? .7 : 1.15, 0));
      if (center.distanceTo(point) > radius + MOB_STATS[mob.kind].radius) continue;
      mob.health = Math.max(0, mob.health - damage); mob.hitFlash = .15; count++;
      mob.root.scale.setScalar(1.08);
      if (mob.health === 0) this.defeat(mob);
    }
    return count;
  }

  update(delta: number, elapsed: number, player: THREE.Vector3, block: (from: THREE.Vector3, to: THREE.Vector3) => boolean) {
    void block; // Mobs use close-range attacks; the old floating sentinels' homing shots are intentionally gone.
    for (const mob of this.mobs) {
      if (mob.health <= 0) {
        mob.respawnTimer -= delta;
        mob.deathAge += delta;
        if (mob.deathAge < .8) this.animateDefeat(mob);
        else mob.root.visible = false;
        if (mob.respawnTimer <= 0) this.respawn(mob, elapsed);
        continue;
      }
      mob.root.scale.setScalar(THREE.MathUtils.damp(mob.root.scale.x, 1, 18, delta));
      const wasFlashing = mob.hitFlash > 0;
      mob.hitFlash = Math.max(0, mob.hitFlash - delta);
      if (wasFlashing) mob.root.traverse(object => {
          if (!(object instanceof THREE.Mesh)) return;
          const material = object.material;
          if (!(material instanceof THREE.MeshStandardMaterial) || object.userData.eye) return;
          material.emissiveIntensity = (object.userData.baseEmissive ?? .03) + mob.hitFlash * 2.5;
        });

      const dx = player.x - mob.root.position.x, dz = player.z - mob.root.position.z;
      const distance = Math.hypot(dx, dz);
      const stats = MOB_STATS[mob.kind];
      mob.attackTimer -= delta;
      const isMoving = distance > stats.range * .8 && distance < 26 && mob.attackPhase <= 0;
      const targetYaw = Math.atan2(dx, dz);
      const angleDelta = THREE.MathUtils.euclideanModulo(targetYaw - mob.root.rotation.y + Math.PI, Math.PI * 2) - Math.PI;
      mob.root.rotation.y += angleDelta * (1 - Math.exp(-delta * (isMoving ? 5 : 8)));
      mob.root.position.y = terrainHeight(mob.root.position.x, mob.root.position.z) + Math.sin(elapsed * (mob.kind === 'wolf' ? 8 : 3.5) + mob.phase) * (mob.kind === 'wolf' ? .025 : .012);
      if (isMoving) {
        const stride = Math.min(stats.speed * delta, Math.max(0, distance - stats.range * .8));
        mob.root.position.x += (dx / Math.max(distance, .001)) * stride;
        mob.root.position.z += (dz / Math.max(distance, .001)) * stride;
        mob.root.position.y = terrainHeight(mob.root.position.x, mob.root.position.z);
      }
      if (mob.attackPhase <= 0 && distance <= stats.range && mob.attackTimer <= 0) {
        mob.attackTimer = stats.cadence;
        mob.attackDuration = mob.kind === 'wolf' ? .72 : mob.kind === 'bandit' ? .82 : .94;
        mob.attackPhase = mob.attackDuration;
        mob.attackHit = false;
      }
      this.animateMob(mob, delta, elapsed, isMoving);
      if (mob.attackPhase > 0) {
        const progress = 1 - mob.attackPhase / mob.attackDuration;
        if (!mob.attackHit && progress >= .48) {
          mob.attackHit = true;
          const strikeDistance = Math.hypot(player.x - mob.root.position.x, player.z - mob.root.position.z);
          if (strikeDistance <= stats.range + .35 && !block(player.clone().add(new THREE.Vector3(0, .9, 0)), mob.root.position.clone().add(new THREE.Vector3(0, 1, 0)))) {
            this.health = Math.max(0, this.health - stats.damage);
          }
        }
        mob.attackPhase = Math.max(0, mob.attackPhase - delta);
      }
    }

    for (let index = this.drops.length - 1; index >= 0; index--) {
      const drop = this.drops[index]; drop.age += delta;
      if (drop.age > 120) { this.removeDrop(drop, index); continue; }
      drop.root.rotation.y += delta * 1.3;
      drop.root.position.y = terrainHeight(drop.root.position.x, drop.root.position.z) + .48 + Math.sin(drop.age * 3.5) * .12;
      if (Math.hypot(drop.root.position.x - player.x, drop.root.position.z - player.z) < 1.55) {
        if (drop.kind === 'experience') { this.onExperience(drop.value); this.onPickup(`+${drop.value} XP`); }
        else { this.onItem(drop.kind); this.onPickup(`Item encontrado: ${drop.kind === 'moonFang' ? 'Presa lunar' : drop.kind === 'ancientSigil' ? 'Selo ancestral' : drop.kind === 'demonHeart' ? 'Coração demoníaco' : drop.kind === 'wolfPelt' ? 'Pele de lobo' : drop.kind === 'banditToken' ? 'Ficha de bandido' : 'Cinza demoníaca'}`); }
        this.removeDrop(drop, index);
      }
    }
  }

  dispose() {
    this.root.removeFromParent(); this.dropRoot.removeFromParent();
    this.geometries.forEach(geometry => geometry.dispose());
    this.materials.forEach(material => material.dispose());
  }

  private geometry<T extends THREE.BufferGeometry>(geometry: T) { this.geometries.push(geometry); return geometry; }
  private material(color: string, emissive = '#000000', emissiveIntensity = .03, roughness = .82) {
    const material = new THREE.MeshStandardMaterial({ color, emissive: emissive === '#000000' ? color : emissive, emissiveIntensity: emissive === '#000000' ? .72 : emissiveIntensity, roughness, flatShading: false });
    this.materials.push(material); return material;
  }

  private createMob(spawn: Spawn, index: number): Mob {
    const root = new THREE.Group(); root.name = `${spawn.kind}-mob`; root.position.set(spawn.x, terrainHeight(spawn.x, spawn.z), spawn.z); this.root.add(root);
    const legs: THREE.Group[] = [], arms: THREE.Group[] = [];
    const rig = this.buildMob(root, spawn.kind, legs, arms);
    const { target } = rig;
    this.targets.push(target);
    const stats = MOB_STATS[spawn.kind];
    return { kind: spawn.kind, root, ...rig, health: stats.hp, phase: Math.random() * 6, attackTimer: 1 + Math.random() * 1.8, respawnTimer: 0, spawn: index, hitFlash: 0, legs, arms, attackPhase: 0, attackDuration: 1, attackHit: false, gait: Math.random() * Math.PI * 2, deathAge: 0 };
  }

  private animateMob(mob: Mob, delta: number, elapsed: number, moving: boolean) {
    const phase = elapsed * (mob.kind === 'wolf' ? 9 : 7.2) + mob.gait;
    const stride = moving ? 1 : 0;
    const attack = mob.attackPhase > 0 ? 1 - mob.attackPhase / mob.attackDuration : 0;
    const windup = attack > 0 ? 1 - THREE.MathUtils.smoothstep(attack, .12, .42) : 0;
    const swing = attack > 0 ? Math.sin(THREE.MathUtils.smoothstep(attack, .39, .66) * Math.PI) : 0;
    const recover = attack > 0 ? THREE.MathUtils.smoothstep(attack, .62, 1) : 0;
    const idle = Math.sin(elapsed * 2.3 + mob.phase);

    if (mob.kind === 'wolf') {
      mob.body.position.y = .82 + Math.abs(Math.sin(phase * .5)) * .055 * stride + idle * .018;
      mob.body.position.z = -.08 - windup * .11 + swing * .2 - recover * .04;
      mob.body.rotation.x = Math.sin(phase) * .055 * stride - windup * .19 + swing * .38 + mob.hitFlash * 1.3;
      mob.body.rotation.z = Math.sin(phase * .5) * .045 * stride;
      mob.head.rotation.x = -.04 + Math.sin(phase * .5) * .035 * stride + windup * .28 - swing * .64 - mob.hitFlash * .55;
      mob.head.rotation.y = Math.sin(elapsed * 1.4 + mob.phase) * .04;
      if (mob.tail) {
        mob.tail.rotation.x = .18 + Math.sin(elapsed * 5 + mob.phase) * .15 + windup * .18;
        mob.tail.rotation.y = Math.sin(elapsed * 4.2 + mob.phase) * .3;
      }
      mob.legs.forEach((leg, index) => {
        const gait = Math.sin(phase + (leg.userData.gaitPhase as number));
        leg.rotation.x = gait * .46 * stride;
        if (attack > 0 && index < 2) leg.rotation.x -= windup * .2 + swing * .48;
      });
    } else {
      mob.body.position.y = 1.12 + idle * .012;
      mob.body.position.z = -windup * .08 + swing * .12 - recover * .025;
      mob.body.rotation.x = Math.sin(phase) * .025 * stride + windup * .1 - swing * .13 + mob.hitFlash * 1.15;
      mob.body.rotation.y = Math.sin(phase * .5) * .035 * stride + windup * (mob.kind === 'bandit' ? -.28 : .2) - swing * (mob.kind === 'bandit' ? -.38 : .26);
      mob.body.scale.y = 1 + Math.sin(elapsed * 2 + mob.phase) * .012;
      mob.head.rotation.x = Math.sin(elapsed * 1.6 + mob.phase) * .025 + windup * .12 - swing * .2 - mob.hitFlash * .4;
      mob.head.rotation.y = Math.sin(elapsed * 1.1 + mob.phase) * .045;
      mob.legs.forEach((leg, index) => { leg.rotation.x = Math.sin(phase + (leg.userData.gaitPhase as number)) * .55 * stride; });
      mob.arms.forEach((arm, index) => {
        const side = index === 0 ? -1 : 1;
        arm.rotation.x = Math.sin(phase + (index === 0 ? Math.PI : 0)) * .09 * stride;
        arm.rotation.z = side * (-.08 + Math.sin(phase + index * Math.PI) * .04 * stride);
      });
      if (mob.kind === 'bandit' && mob.arms[1]) {
        mob.arms[1].rotation.x += -windup * .68 + swing * 1.35 + recover * .16;
        mob.arms[1].rotation.z += -windup * .4 + swing * .7;
        if (mob.arms[0]) mob.arms[0].rotation.x += windup * .25 - swing * .15;
      } else if (mob.kind === 'demon') {
        mob.arms.forEach((arm, index) => {
          arm.rotation.x += -windup * (index === 1 ? .72 : .45) + swing * (index === 1 ? 1.25 : .72) + recover * .1;
          arm.rotation.z += (index === 0 ? 1 : -1) * (windup * .48 - swing * .55);
        });
      }
      const braids = mob.head.userData.braids as THREE.Group[] | undefined;
      braids?.forEach((braid, index) => {
        braid.rotation.x = .08 + Math.sin(elapsed * 3.4 + index * Math.PI + mob.phase) * .11 + Math.sin(phase) * .05 * stride;
        braid.rotation.z = Math.sin(elapsed * 2.6 + index + mob.phase) * .08;
      });
    }
    void delta;
  }

  private animateDefeat(mob: Mob) {
    const fall = THREE.MathUtils.smoothstep(mob.deathAge, 0, .72);
    const side = mob.phase % 2 < 1 ? 1 : -1;
    if (mob.kind === 'wolf') {
      mob.body.position.y = .82 - fall * .35;
      mob.body.position.z = -.08;
      mob.body.rotation.z = side * fall * .95;
      mob.head.rotation.x = fall * .55;
      mob.legs.forEach((leg, index) => { leg.rotation.x = (index < 2 ? -.7 : .7) * fall; leg.rotation.z = (index % 2 ? 1 : -1) * .35 * fall; });
      if (mob.tail) mob.tail.rotation.x = .18 + fall * .7;
    } else {
      mob.body.position.y = 1.12 - fall * .52;
      mob.body.position.z = 0;
      mob.body.rotation.z = side * fall * .95;
      mob.head.rotation.x = .16 * fall;
      mob.legs.forEach((leg, index) => { leg.rotation.x = (index ? .35 : -.35) * fall; });
      mob.arms.forEach((arm, index) => { arm.rotation.x = -.7 * fall; arm.rotation.z = (index ? -1 : 1) * .7 * fall; });
    }
  }

  private buildMob(root: THREE.Group, kind: MobKind, legs: THREE.Group[], arms: THREE.Group[]) {
    const hide = this.material('#26272b');
    const fur = this.material(kind === 'wolf' ? '#77766d' : kind === 'bandit' ? '#423a37' : '#522f32', kind === 'demon' ? '#6b2022' : '#000000', kind === 'demon' ? .42 : .025);
    const accent = this.material(kind === 'wolf' ? '#aaa395' : kind === 'bandit' ? '#756449' : '#a14d3c', kind === 'demon' ? '#992f25' : '#000000', kind === 'demon' ? .4 : .025);
    const skin = this.material(kind === 'wolf' ? '#a69e8f' : kind === 'bandit' ? '#a47e61' : '#782e2e', kind === 'demon' ? '#8c2824' : '#000000', kind === 'demon' ? .48 : .025);
    const eye = this.material(kind === 'demon' ? '#ff9b63' : '#ddbd76', kind === 'demon' ? '#ef3d2c' : '#8c552a', 1.3, .25);
    const gold = kind === 'demon' ? this.material('#d7b66d', '#74532b', .12, .42) : accent;
    const fill = new THREE.PointLight(kind === 'demon' ? '#d24e43' : kind === 'wolf' ? '#c5a16c' : '#b39164', kind === 'demon' ? .55 : .28, kind === 'demon' ? 4.8 : 3.2, 2);
    fill.position.set(0, 1.15, .15); root.add(fill);
    if (kind === 'wolf') {
      const body = new THREE.Group(); body.position.set(0, .82, -.08); root.add(body);
      part(body, this.sphere, fur, [0, 0, 0], [.48, .43, .82]);
      part(body, this.sphere, accent, [0, -.11, .13], [.34, .25, .58]);
      part(body, this.sphere, fur, [0, .07, .53], [.42, .44, .39]);
      part(body, this.sphere, fur, [0, .1, -.48], [.49, .45, .4]);
      const neck = new THREE.Group(); neck.position.set(0, .12, .42); body.add(neck);
      part(neck, this.capsule, fur, [0, .12, .04], [.84, .92, .93], [-.54, 0, 0]);
      part(neck, this.sphere, accent, [0, -.06, .24], [.29, .28, .3]);
      const head = new THREE.Group(); head.position.set(0, .23, .42); neck.add(head);
      part(head, this.sphere, fur, [0, .02, .06], [.35, .33, .38]);
      part(head, this.sphere, accent, [0, -.1, .34], [.24, .18, .38]);
      part(head, this.sphere, skin, [0, -.12, .55], [.18, .12, .22]);
      part(head, this.sphere, hide, [0, -.07, .73], [.095, .075, .09]);
      for (const side of [-1, 1]) {
        const ear = part(head, this.cone, fur, [side * .22, .38, -.06], [.62, .82, .56], [side * -.18, 0, side * -.17]);
        part(head, this.cone, skin, [side * .22, .4, .015], [.38, .55, .34], [side * -.18, 0, side * -.17]);
        const eyeMesh = part(head, this.sphere, eye, [side * .22, .1, .35], [.052, .046, .038]); eyeMesh.userData.eye = true;
        part(head, this.sphere, hide, [side * .22, .1, .377], [.082, .066, .05]);
        part(head, this.sphere, eye, [side * .22, .1, .405], [.032, .03, .025]);
        void ear;
      }
      const tail = new THREE.Group(); tail.position.set(0, .04, -.72); body.add(tail);
      tail.rotation.x = .34;
      let tailParent: THREE.Object3D = tail;
      for (let i = 0; i < 3; i++) {
        const segment = new THREE.Group(); segment.position.set(0, i === 0 ? 0 : -.035, -.23); tailParent.add(segment);
        part(segment, this.sphere, i === 2 ? accent : fur, [0, 0, -.18], [.22 - i * .035, .24 - i * .035, .31]);
        tailParent = segment;
      }
      for (const x of [-1, 1]) for (const z of [.46, -.5]) {
        const leg = new THREE.Group(); leg.position.set(x * (z > 0 ? .31 : .34), .68, z); root.add(leg);
        if (z < 0) part(leg, this.sphere, fur, [0, -.04, -.015], [.24, .31, .27]);
        part(leg, this.capsule, fur, [0, -.31, 0], [.58, .5, .6]);
        const paw = new THREE.Group(); paw.position.set(0, -.57, .07); leg.add(paw);
        part(paw, this.sphere, hide, [0, -.02, .08], [.16, .1, .22]);
        for (const toe of [-1, 0, 1]) part(paw, this.sphere, hide, [toe * .09, -.025, .22], [.065, .068, .1]);
        leg.userData.gaitPhase = x * z > 0 ? 0 : Math.PI;
        legs.push(leg);
      }
      const target = part(head, this.sphere, this.targetMaterial, [0, -.02, .42], [.28, .22, .34]); target.name = 'wolf-target';
      return { target, body, head, tail };
    }

    const body = new THREE.Group(); body.position.set(0, 1.12, 0); root.add(body);
    const head = new THREE.Group(); head.position.set(0, .78, .02); body.add(head);
    part(body, this.capsule, kind === 'bandit' ? fur : skin, [0, -.12, 0], kind === 'demon' ? [1.12, 1.08, .96] : [1, 1, 1]);
    part(body, this.sphere, kind === 'bandit' ? accent : fur, [0, -.32, -.04], [.55, .34, .42]);
    part(head, this.sphere, skin, [0, .02, 0], kind === 'demon' ? [.34, .4, .3] : [.32, .36, .3]);
    if (kind === 'bandit') {
      part(head, this.cone, fur, [0, .23, -.02], [1.8, .66, 1.45]);
      part(head, this.box, accent, [0, -.14, .27], [.55, .12, .08], [0, 0, -.08]);
      part(head, this.box, hide, [0, -.02, .27], [.48, .19, .07]);
      for (const side of [-1, 1]) {
        const eyeMesh = part(head, this.sphere, eye, [side * .12, .06, .29], [.045, .035, .028]);
        eyeMesh.userData.eye = true;
      }
      part(body, this.box, accent, [0, .08, .3], [.82, .1, .07], [0, 0, -.35]);
      part(body, this.box, accent, [0, -.32, .28], [.7, .12, .07], [0, 0, .28]);
      part(body, this.sphere, hide, [.48, -.1, 0], [.2, .25, .22]);
    } else {
      const hair = this.material('#ad4c91', '#612553', .16, .6);
      const hairLight = this.material('#d76cb0', '#8b3975', .1, .54);
      const horn = this.material('#ded0ca', '#4b3037', .12, .34);
      part(head, this.sphere, hair, [0, .17, -.1], [.39, .39, .36]);
      part(head, this.sphere, hair, [0, -.12, -.22], [.36, .56, .23]);
      const braids: THREE.Group[] = [];
      for (const side of [-1, 1]) {
        const braid = new THREE.Group(); braid.position.set(side * .27, .08, -.03); head.add(braid);
        braids.push(braid);
        for (let i = 0; i < 5; i++) part(braid, this.sphere, i % 2 ? hairLight : hair, [side * .055, -.12 - i * .13, -.05 + (i % 2) * .035], [.13 - i * .008, .16, .14]);
        const eyeMesh = part(head, this.sphere, eye, [side * .14, .04, .265], [.045, .042, .03]); eyeMesh.userData.eye = true;
        part(head, this.sphere, hide, [side * .14, .04, .282], [.064, .052, .025]);
        part(head, this.sphere, eye, [side * .14, .04, .3], [.029, .03, .02]);
        const hornCurve = new THREE.CatmullRomCurve3([
          new THREE.Vector3(side * .23, .29, -.03), new THREE.Vector3(side * .34, .54, -.06),
          new THREE.Vector3(side * .37, .79, -.12), new THREE.Vector3(side * .29, .98, -.2),
        ]);
        const hornGeometry = this.geometry(new THREE.TubeGeometry(hornCurve, 12, .075, 8, false));
        part(head, hornGeometry, horn, [0, 0, 0]);
        part(body, this.sphere, gold, [side * .35, .34, .05], [.08, .08, .06]);
        part(body, this.cone, gold, [side * .4, .24, .07], [.28, .18, .22], [0, 0, side * .3]);
      }
      head.userData.braids = braids;
      part(body, this.cone, fur, [0, -.72, -.03], [2.75, 1.25, 2.4]);
      part(body, this.cylinder, gold, [0, -.48, .03], [.87, .08, .87]);
      part(body, this.box, accent, [0, .02, .29], [.48, .54, .11]);
      part(body, this.box, gold, [0, .03, .36], [.045, .52, .025]);
      part(body, this.sphere, eye, [0, .35, .15], [.08, .09, .08]);
    }
    for (const side of [-1, 1]) {
      const arm = new THREE.Group(); arm.position.set(side * .5, .38, 0); body.add(arm);
      part(arm, this.capsule, kind === 'demon' ? skin : accent, [0, -.24, 0], [.74, .9, .76]);
      part(arm, this.sphere, skin, [0, -.49, .08], [.18, .17, .18]); arms.push(arm);
      if (side > 0) {
        const blade = kind === 'bandit' ? this.box : this.cone;
        const weapon = part(arm, blade, kind === 'bandit' ? hide : accent, [0, -.08, .31], kind === 'bandit' ? [.09, .8, .07] : [.42, 1.1, .42], [0, 0, -.12]);
        if (kind === 'bandit') {
          part(arm, this.box, gold, [0, -.46, .25], [.22, .07, .08]);
          part(arm, this.box, accent, [0, -.16, .3], [.17, .2, .15], [0, 0, -.12]);
        } else for (const clawSide of [-1, 1]) part(arm, this.cone, hide, [clawSide * .1, -.53, .23], [.23, .72, .2], [clawSide * .28, 0, 0]);
        weapon.name = kind === 'bandit' ? 'bandit-blade' : 'demon-claw';
      }
      if (kind === 'demon') part(arm, this.cylinder, gold, [0, -.16, .02], [.94, .08, .94]);
      const leg = new THREE.Group(); leg.position.set(side * .22, .96, 0); root.add(leg);
      part(leg, this.capsule, kind === 'demon' ? skin : fur, [0, -.27, 0], [.68, .9, .72]);
      part(leg, this.sphere, hide, [0, -.84, .12], [.17, .11, .24]);
      leg.userData.gaitPhase = side > 0 ? 0 : Math.PI;
      legs.push(leg);
    }
    const target = part(head, this.sphere, this.targetMaterial, [0, .02, .19], [.35, .48, .34]); target.name = `${kind}-target`;
    return { body, head, tail: null, target };
  }

  private defeat(mob: Mob) {
    mob.root.visible = true;
    mob.deathAge = 0;
    mob.respawnTimer = 12 + Math.random() * 8;
    const stats = MOB_STATS[mob.kind];
    this.spawnDrop('experience', mob.root.position, stats.xp);
    const roll = Math.random();
    const loot: LootItemId | undefined = mob.kind === 'wolf'
      ? roll < .045 ? 'moonFang' : roll < .32 ? 'wolfPelt' : undefined
      : mob.kind === 'bandit'
        ? roll < .055 ? 'ancientSigil' : roll < .36 ? 'banditToken' : undefined
        : roll < .1 ? 'demonHeart' : roll < .42 ? 'demonAsh' : undefined;
    if (loot) this.spawnDrop(loot, mob.root.position, 1);
  }

  private spawnDrop(kind: Drop['kind'], position: THREE.Vector3, value: number) {
    const root = new THREE.Group(); root.position.copy(position); this.dropRoot.add(root);
    const temporaryMaterials: THREE.Material[] = [];
    const material = kind === 'experience' ? this.xpMaterial : this.material(LOOT[kind].color, LOOT[kind].color, .45, .32);
    if (kind !== 'experience') temporaryMaterials.push(material);
    const gem = new THREE.Mesh(this.gemGeometry, material);
    if (kind !== 'experience') gem.scale.setScalar(.84);
    gem.castShadow = false; root.add(gem);
    const ringMat = new THREE.MeshBasicMaterial({ color: kind === 'experience' ? '#b9dcc2' : LOOT[kind].color, transparent: true, opacity: .62 });
    this.materials.push(ringMat);
    temporaryMaterials.push(ringMat);
    const ring = new THREE.Mesh(this.ringGeometry, ringMat); ring.rotation.x = Math.PI / 2; root.add(ring);
    const light = new THREE.PointLight(kind === 'experience' ? '#93c5a2' : LOOT[kind].color, .45, 3); root.add(light);
    this.drops.push({ root, kind, age: Math.random() * 4, value, materials: temporaryMaterials });
  }

  private removeDrop(drop: Drop, index: number) {
    drop.root.removeFromParent();
    drop.materials.forEach(material => { material.dispose(); this.materials.splice(this.materials.indexOf(material), 1); });
    this.drops.splice(index, 1);
  }

  private respawn(mob: Mob, elapsed: number) {
    const choices = SPAWNS.map((spawn, index) => ({ spawn, index })).filter(entry => entry.spawn.kind === mob.kind);
    const next = choices[(Math.floor(elapsed / 6) + mob.spawn + 1) % choices.length];
    mob.spawn = next.index; mob.root.position.set(next.spawn.x, terrainHeight(next.spawn.x, next.spawn.z), next.spawn.z);
    mob.root.rotation.set(0, 0, 0); mob.root.scale.setScalar(1); mob.root.visible = true; mob.health = MOB_STATS[mob.kind].hp;
    mob.body.position.set(0, mob.kind === 'wolf' ? .82 : 1.12, mob.kind === 'wolf' ? -.08 : 0);
    mob.body.rotation.set(0, 0, 0); mob.body.scale.set(1, 1, 1); mob.head.rotation.set(0, 0, 0);
    mob.legs.forEach(leg => leg.rotation.set(0, 0, 0)); mob.arms.forEach(arm => arm.rotation.set(0, 0, 0));
    if (mob.tail) mob.tail.rotation.set(.34, 0, 0);
    mob.attackPhase = 0; mob.attackHit = false; mob.deathAge = 0; mob.hitFlash = 0;
    mob.attackTimer = 1.2 + Math.random() * 1.4; mob.respawnTimer = 0;
  }
}
